    Dont format sstreams when there's nothing to format

diff --git a/arch/AArch64/AArch64InstPrinter.c b/arch/AArch64/AArch64InstPrinter.c
index 31d31b57..531a8fce 100644
--- a/arch/AArch64/AArch64InstPrinter.c
+++ b/arch/AArch64/AArch64InstPrinter.c
@@ -1479,7 +1479,7 @@ static void printFPImmOperand(MCInst *MI, unsigned OpNum, SStream *O)
        // 8 decimal places are enough to perfectly represent permitted floats.
 #if defined(_KERNEL_MODE)
        // Issue #681: Windows kernel does not support formatting float point
-       SStream_concat(O, "#<float_point_unsupported>");
+       SStream_concat0(O, "#<float_point_unsupported>");
 #else
        SStream_concat(O, "#%.8f", FPImm);
 #endif
diff --git a/arch/EVM/EVMInstPrinter.c b/arch/EVM/EVMInstPrinter.c
index 7f452800..2b02be3e 100644
--- a/arch/EVM/EVMInstPrinter.c
+++ b/arch/EVM/EVMInstPrinter.c
@@ -7,7 +7,7 @@

 void EVM_printInst(MCInst *MI, struct SStream *O, void *PrinterInfo)
 {
-       SStream_concat(O, EVM_insn_name((csh)MI->csh, MI->Opcode));
+       SStream_concat0(O, EVM_insn_name((csh)MI->csh, MI->Opcode));

        if (MI->Opcode >= EVM_INS_PUSH1 && MI->Opcode <= EVM_INS_PUSH32) {
                unsigned int i;
diff --git a/arch/M680X/M680XInstPrinter.c b/arch/M680X/M680XInstPrinter.c
index 83a94909..45b6fbc1 100644
--- a/arch/M680X/M680XInstPrinter.c
+++ b/arch/M680X/M680XInstPrinter.c
@@ -102,7 +102,7 @@ static const name_map s_group_names[] = {
 static void printRegName(cs_struct *handle, SStream *OS, unsigned int reg)
 {
 #ifndef CAPSTONE_DIET
-       SStream_concat(OS, handle->reg_name((csh)handle, reg));
+       SStream_concat0(OS, handle->reg_name((csh)handle, reg));
 #endif
 }

@@ -110,7 +110,7 @@ static void printInstructionName(cs_struct *handle, SStream *OS,
        unsigned int insn)
 {
 #ifndef CAPSTONE_DIET
-       SStream_concat(OS, handle->insn_name((csh)handle, insn));
+       SStream_concat0(OS, handle->insn_name((csh)handle, insn));
 #endif
 }

@@ -147,7 +147,7 @@ static void printIncDec(bool isPost, SStream *O, m680x_info *info,
                        prePostfix = (char *)s_inc_dec[op->idx.inc_dec + 2];
                }

-               SStream_concat(O, prePostfix);
+               SStream_concat0(O, prePostfix);
        }
 }

@@ -174,7 +174,7 @@ static void printOperand(MCInst *MI, SStream *O, m680x_info *info,

        case M680X_OP_INDEXED:
                if (op->idx.flags & M680X_IDX_INDIRECT)
-                       SStream_concat(O, "[");
+                       SStream_concat0(O, "[");

                if (op->idx.offset_reg != M680X_REG_INVALID)
                        printRegName(MI->csh, O, op->idx.offset_reg);
@@ -229,7 +229,7 @@ static void printOperand(MCInst *MI, SStream *O, m680x_info *info,
                break;

        default:
-               SStream_concat(O, "<invalid_operand>");
+               SStream_concat0(O, "<invalid_operand>");
                break;
        }
